import { z } from 'zod';

/**
 * The persisted enum shapes for the SQLite entities — and, since every one of
 * them also travels to the UI on a run / item / node projection, the wire
 * contract for those enums too.
 *
 * Declared as zod enums carrying `.meta({ id })` so they land as NAMED
 * components in the daemon's OpenAPI document, which is what makes the
 * renderer's generated client (`apps/ui/src/renderer/autogenerated`) expose one
 * union type per enum instead of an inline copy per response.
 */

export const RUN_STATUSES = [
  'pending',
  'running',
  'completed',
  'failed',
  'cancelled',
] as const;

export const RunStatusSchema = z.enum(RUN_STATUSES).meta({ id: 'RunStatus' });
export type RunStatus = z.infer<typeof RunStatusSchema>;

/**
 * Statuses a run never leaves. `pending` and `running` are the live ones;
 * everything else is settled.
 *
 * Derived from {@link RUN_STATUSES} by exclusion rather than listed
 * separately, so adding a status forces a decision here instead of silently
 * defaulting to "not terminal" — which would make a settled run look live.
 */
const LIVE_RUN_STATUSES: ReadonlySet<RunStatus> = new Set<RunStatus>([
  'pending',
  'running',
]);

/** Whether a run has settled and will never change status on its own again. */
export function isTerminalRunStatus(status: RunStatus): boolean {
  return !LIVE_RUN_STATUSES.has(status);
}

/** A node may additionally be `skipped` — an upstream node failed. */
export const NodeStatusSchema = z
  .enum([...RUN_STATUSES, 'skipped'])
  .meta({ id: 'NodeStatus' });
export type NodeStatus = z.infer<typeof NodeStatusSchema>;

/**
 * Conversation item kind — the normalized transcript taxonomy. M1 shipped the
 * first 6; M2 widened it to 11; M3 adds the two approval kinds (a plain TEXT
 * column, so the `safe: true` schema sync needs no migration). `message`
 * carries user and assistant text (disambiguated by `Item.role`);
 * `usage`/`status`/`attachment` are defined here for the event model and
 * forward-compat though only a subset is emitted. `approval_request` is an
 * `ask`-node's paused tool call awaiting a verdict; `approval_verdict` records
 * the user's answer, closing the pair for reconnect replay.
 *
 * The agent-calls milestone adds the three call kinds: `call_started` (a
 * caller invoked call_agent — attributed to the CALLER node), `call_result`
 * (the call's envelope settled — also the caller's), and `await_collected`
 * (an async result was picked up via await_agent). The callee's own turn
 * streams as regular items under the callee's nodeId. The Q&A bridge (M4)
 * adds `call_question` (a call-initiated callee raised AskUserQuestion —
 * parked, awaiting the caller) and `call_answer` (how it resolved: answered
 * via answer_agent, TTL timeout, or orphaned by the caller ending) — both
 * attributed to the CALLER node like the other call kinds.
 *
 * `task_list` is one announcement about the agent's OWN task list — the todo
 * list the CLI keeps while it works. Persisted rather than kept live-only
 * because a reopened chat must show the list as it stands, and the list only
 * exists as the sum of its announcements: two of the three shapes on the wire
 * are patches, so a client that missed one cannot reconstruct the rest.
 *
 * `shell_info` closes a BACKGROUND SHELL — a command the agent detached, whose
 * launching tool call returned within the second while the command ran on for
 * minutes. It is the only end signal such a command has: measured on claude
 * 2.1.237, the CLI reports the completion to the MODEL out of band and to the
 * conversation as a sentence the agent writes, so a reader folding "what is
 * running" out of tool calls alone lists it forever. Persisted rather than
 * streamed for the same reason `task_list` is — a reopened chat replays the
 * transcript, and an ephemeral end would show every past background command as
 * running again. It renders as NOTHING; it exists to close a row that is.
 *
 * `unanswerable` closes an `approval_request` that can never be answered now:
 * its turn settled while the request was still pending, so the card on screen
 * is a dead control. The daemon says so explicitly rather than leaving the
 * renderer to infer staleness from a settled turn — an inference that has no
 * way to distinguish a request the CLI abandoned from one still in flight.
 *
 * `report_findings` is a list of code-review findings an agent handed the APP
 * to draw — through geniro's own MCP tool, rather than printing them as prose
 * a transcript can only show as prose. The payload IS the card: the tool call
 * answers with a receipt alone, deliberately, so the findings never re-enter
 * the model's context, which leaves this row as the only place they exist.
 * Persisted rather than streamed for `task_list`'s reason — a reopened chat
 * replays the transcript, and a card that lived only on the wire would be gone
 * from every conversation the moment it was closed.
 *
 * `show_chart` is the second row of that same RENDER family, and everything
 * said about `report_findings` above holds unchanged — the payload is the card,
 * the call answers with a receipt, the row is the only place the data exists.
 * What is its own: the payload is POSITIONAL. Every series holds one value per
 * entry of `labels`, aligned by index, so a reader that drops or reorders
 * either list silently re-attributes measurements instead of failing.
 */
export const ItemKindSchema = z
  .enum([
    'message',
    'reasoning',
    'tool_call',
    'tool_result',
    'turn_complete',
    'turn_cancelled',
    'usage',
    'system',
    'error',
    'attachment',
    'status',
    'approval_request',
    'approval_verdict',
    'unanswerable',
    'call_started',
    'call_result',
    'await_collected',
    'call_question',
    'call_answer',
    'subagent_info',
    'task_list',
    'shell_info',
    'report_findings',
    'show_chart',
  ])
  .meta({ id: 'ItemKind' });
export type ItemKind = z.infer<typeof ItemKindSchema>;

/**
 * A CLI coding agent the daemon can drive headlessly (M2: one at a time).
 *
 * Declared as a value object so an agent is NAMED at every use site
 * (`AgentKind.CursorAgent`) rather than spelled as a bare string a typo turns
 * into a silently unmatched branch. The schema is derived FROM it, so the
 * vocabulary cannot drift from the names, and the shape deliberately mirrors
 * the `AgentKind` the renderer already receives in `autogenerated/` — both
 * sides of the wire spell an agent the same way.
 */
export const AgentKind = {
  Claude: 'claude',
  CursorAgent: 'cursor-agent',
} as const;

export const AgentKindSchema = z.enum(AgentKind).meta({ id: 'AgentKind' });
export type AgentKind = z.infer<typeof AgentKindSchema>;
